    ('cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Quiz — Une frise de conquêtes', 'Sport', '1re', 'Les femmes dans le sport : d’Alice Milliat à la parité', '88064ea8-aaca-56d3-b9da-9e3ac232b1df'::uuid),
    ('6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Quiz — D’où vient l’argent du sport', 'Sport', '1re', 'Le sport business : droits TV, sponsors, salaires', '61dd6f7b-05bd-5266-8383-997d13ec0a6d'::uuid),
    ('8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Quiz — Pourquoi on triche, et pourquoi ça ne vaut pas le coup', 'Sport', '1re', 'Le dopage : de Festina à l’AMA', 'bdbf28f6-dd3c-568a-9328-d397b47fea83'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('8a589061-5459-57c6-b3c3-7e477ccf0e26'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Quelle molécule le muscle utilise-t-il directement pour se contracter ?', 'mcq', '["L’oxygène","L’ATP","Le lactate","Le glucose seul"]'::jsonb, 1, 'Le muscle ne sait dépenser que de l’ATP ; toutes les filières servent à en refabriquer.', 1),
    ('df30e9da-fcef-581f-a163-aa678041e3f2'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Combien de filières énergétiques le corps utilise-t-il pour refabriquer l’ATP ?', 'mcq', '["Trois","Cinq","Une seule","Deux"]'::jsonb, 0, 'Il y en a trois : alactique, lactique et aérobie, qui se chevauchent en permanence.', 2),
    ('5a462a05-b93e-5919-a75d-7d74960e0258'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Quelle filière domine pendant un sprint de 100 m ?', 'mcq', '["L’anaérobie lactique","L’anaérobie alactique","Aucune, le corps se repose","L’aérobie"]'::jsonb, 1, 'Sur les premières secondes, la phosphocréatine déjà stockée fournit l’énergie : c’est très puissant mais ça ne dure qu’une dizaine de secondes.', 3),
    ('67d26a01-94a7-5641-b50f-28e1720101e3'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Un 400 m ou un 100 m nage sollicite surtout la filière anaérobie lactique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Entre environ 10 secondes et 2 minutes, la glycolyse sans oxygène domine : c’est la zone du 400 m et du 100 m nage.', 4),
    ('aca53c05-3c51-53c5-ab41-212a108aab23'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Quelle filière est « inépuisable » mais moins puissante ?', 'mcq', '["L’alactique","L’aérobie","La lactique","Aucune"]'::jsonb, 1, 'Avec l’oxygène, glucides et lipides peuvent être brûlés longtemps, mais plus lentement : idéal pour le 10 km et le marathon.', 5),
    ('a5337a7d-bd23-5f67-ab55-7cf28dc091fb'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Le lactate est un poison qui provoque les courbatures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le lactate est un carburant recyclé par le cœur, les muscles et le foie ; les courbatures viennent de micro-lésions des fibres.', 6),
    ('6d4c27c6-08bf-5293-b539-2dd59e65ad5c'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Comment entraîne-t-on surtout la filière alactique ?', 'mcq', '["Des étirements","De longues sorties à allure lente","Des efforts très courts et maximaux, avec récupération complète","Des séries de 10 minutes sans repos"]'::jsonb, 2, 'Le stock de phosphocréatine ne se reconstitue qu’au repos : il faut récupérer complètement entre deux efforts pour rester explosif.', 7),
    ('227564aa-c881-5e76-93e3-f5a86d453c2e'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Pour entraîner la filière lactique, on utilise plutôt…', 'mcq', '["Des séries de 30 secondes à 2 minutes à forte intensité","Des siestes","Des sprints de 3 secondes","Une marche tranquille d’une heure"]'::jsonb, 0, 'C’est la durée où la glycolyse domine : des séries de 30 s à 2 min en poussant fort la sollicitent directement.', 8),
    ('b535a7f0-147c-5450-b23a-ad8547432e27'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Pendant un marathon, quelle filière fournit presque toute l’énergie ?', 'mcq', '["La phosphocréatine seule","La lactique seule","L’aérobie","L’alactique"]'::jsonb, 2, 'Sur plusieurs heures, seule la filière aérobie peut suivre : elle brûle glucides puis lipides avec de l’oxygène.', 9),
    ('a38aed4c-2bf1-57cb-8a7b-2d4a45109b93'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Les trois filières s’allument l’une après l’autre, jamais en même temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles tournent toujours ensemble ; c’est l’intensité et la durée qui décident de celle qui domine.', 10),
    ('282f8899-384f-5178-9562-6e5d45626df8'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Que signifie « anaérobie » ?', 'mcq', '["Avec beaucoup d’oxygène","Sans oxygène","Sans sucre","Sans effort"]'::jsonb, 1, 'Les filières anaérobies produisent l’ATP sans oxygène : c’est immédiat et puissant, mais ça s’épuise vite.', 11),
    ('662ce448-9829-56c4-a679-3e4c0b3f6c79'::uuid, '39154c1e-7a80-5702-8cfc-cbb75a263788'::uuid, 'Pourquoi un footballeur doit-il entraîner les trois filières ?', 'mcq', '["Il enchaîne démarrages, efforts intenses et récupérations pendant tout le match","Il ne court jamais vite","Il n’utilise que l’aérobie","Les filières n’existent pas en football"]'::jsonb, 0, 'Un match mêle explosivité, séquences intenses et un moteur aérobie qui récupère vite entre les actions.', 12),
    ('36822cfd-a574-5d7f-a8b2-c972544eb3b3'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Que désigne le « volume » d’un entraînement ?', 'mcq', '["Le nombre de jours de repos","La quantité de travail : durée, distance, répétitions","La difficulté de l’effort","Le bruit de la musique"]'::jsonb, 1, 'Le volume mesure la quantité faite ; la difficulté, c’est l’intensité.', 1),
    ('b9a65205-a28c-52e1-ba81-d1c37e84ee4b'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Que signifient les lettres de FITT ?', 'mcq', '["Fréquence, Intensité, Temps, Type","Fatigue, Inertie, Travail, Tension","Fitness, Initiation, Tests, Terrain","Force, Impact, Technique, Tempo"]'::jsonb, 0, 'FITT rappelle les quatre questions à se poser : combien de fois, à quelle difficulté, combien de temps, quel type d’exercice.', 2),
    ('832a4c80-6dd0-5df9-a959-c6d2fabcab38'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'De combien peut-on augmenter la charge de travail chaque semaine, environ ?', 'mcq', '["100 %","50 %","10 %","0 %"]'::jsonb, 2, 'Environ 10 % par semaine : assez pour progresser, assez peu pour que le corps s’adapte sans se blesser.', 3),
    ('fa369ea4-15da-5118-8a0c-4150519981bb'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Pour progresser vite, il vaut mieux changer tous les réglages à la fois.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne modifie qu’un réglage à la fois : sinon on ne sait plus ce qui marche, et le corps encaisse mal.', 4),
    ('8d813060-37a8-5c7c-b12a-20c15cc63224'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Que dit le principe de spécificité ?', 'mcq', '["Il ne faut jamais changer d’exercice","Tous les sports se valent","On progresse dans ce qu’on travaille","Il faut s’entraîner seul"]'::jsonb, 2, 'Courir améliore la course, pas la natation : l’entraînement doit ressembler à ce qu’on veut améliorer.', 5),
    ('98e4accc-853c-57a2-8d1f-377ed2ab8f1a'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Après combien de temps d’arrêt les acquis commencent-ils à redescendre ?', 'mcq', '["Après 2 ans","Environ 2 à 3 semaines","Après 24 heures","Jamais"]'::jsonb, 1, 'C’est la réversibilité : sans entraînement, le corps perd ses adaptations en quelques semaines.', 6),
    ('603f88c9-8878-58eb-8c84-81b7c8b70570'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Où se fait réellement le progrès ?', 'mcq', '["Pendant la récupération, après la séance","Pendant les repas seulement","Nulle part, tout est inné","Uniquement pendant la séance"]'::jsonb, 0, 'La séance donne le signal, mais c’est au repos que le corps se reconstruit plus solide.', 7),
    ('6509fbed-55dc-5840-9647-e0ffad50630c'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Quel est l’intérêt d’un carnet d’entraînement ?', 'mcq', '["Impressionner ses amis","Remplacer la séance","Voir ce qui marche et repérer les signes de fatigue","Compter les calories des autres"]'::jsonb, 2, 'En notant séance, ressenti et fréquence cardiaque, on repère les tendances et on ajuste le programme.', 8),
    ('41117fa0-fe48-54d0-815c-4de43e48b4c9'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Un sportif fatigué en permanence, qui stagne et dort mal doit forcer davantage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les signes du surentraînement : la bonne réponse est de lever le pied quelques jours.', 9),
    ('651fbb79-baf3-5e9a-8b57-bc9881a652ad'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Que mesure l’« intensité » d’une séance ?', 'mcq', '["La difficulté de l’effort, par exemple en % de la VMA","La durée de la séance","Le prix du matériel","Le nombre de spectateurs"]'::jsonb, 0, 'L’intensité se règle en pourcentage de la VMA, de la charge maximale ou de la fréquence cardiaque maximale.', 10),
    ('d03765f1-6bea-55f0-8d4b-468c4ce29a31'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Pourquoi varier les exercices au fil du programme ?', 'mcq', '["Pour perdre du temps","Pour supprimer la récupération","Pour changer de club","Pour éviter l’ennui et les blessures de répétition"]'::jsonb, 3, 'C’est le principe de variété : changer les gestes ménage les articulations et garde la motivation.', 11),
    ('35d476bf-7cbe-5994-ad25-ac1e8e859082'::uuid, '8a98ac19-96db-5448-81cc-812bbadd68cd'::uuid, 'Le programme d’un autre sportif convient forcément à tout le monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’individualisation impose d’adapter le programme à son âge, son niveau, son objectif et son sommeil.', 12),
    ('ce6fa3b9-fec3-5293-aa47-1e5241c6bb78'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Pour développer la force maximale, quelle fourchette de répétitions vise-t-on ?', 'mcq', '["6 à 12","15 à 30","50 et plus","1 à 5"]'::jsonb, 3, 'Une charge très lourde ne se soulève que peu de fois : la force maximale se travaille entre 1 et 5 répétitions.', 1),
    ('d5f4d365-97fc-524d-a5b6-a314965fba25'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Quelle fourchette de répétitions correspond à l’hypertrophie ?', 'mcq', '["1 à 3","6 à 12","30 à 50","Un nombre quelconque"]'::jsonb, 1, 'Entre 6 et 12 répétitions à 65-85 % du max : assez de tension pour faire grossir le muscle.', 2),
    ('a1efff17-f4dc-5736-a68b-5d167ba4371e'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'La puissance, c’est…', 'mcq', '["La taille du muscle","La force multipliée par la vitesse","La force seule","L’endurance multipliée par la durée"]'::jsonb, 1, 'Être puissant, c’est savoir produire de la force vite : un athlète fort mais lent manque de puissance.', 3),
    ('b4d1d4b2-dc76-5cd1-b2df-27667d0b5ce4'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Comment travaille-t-on surtout la puissance ?', 'mcq', '["Séries de 50 répétitions","Étirements prolongés","Charges moyennes soulevées vite et pliométrie","Charges maximales très lentes"]'::jsonb, 2, 'Il faut associer force et vitesse : charges moyennes mouvées rapidement, sauts et lancers.', 4),
    ('935171cb-14c7-58a2-abec-1cd604a06db3'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Un lycéen soulève 60 kg pour 10 répétitions. Quel est son max estimé avec la formule d’Epley ?', 'mcq', '["Environ 80 kg","Environ 100 kg","Environ 60 kg","Environ 70 kg"]'::jsonb, 0, 'Epley : 60 × (1 + 10 / 30) = 60 × 1,33, soit environ 80 kg.', 5),
    ('678d2980-55b9-5947-9e11-33529b7c83f2'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Pourquoi estime-t-on son max plutôt que de le tester ?', 'mcq', '["Pour éviter le risque d’une répétition maximale","Parce que ça ne sert à rien","Parce que le max n’existe pas","Pour soulever plus lourd"]'::jsonb, 0, 'Tester un maximum, surtout sans pareur, expose aux blessures ; la formule donne un repère sûr.', 6),
    ('696e074e-14b0-5305-9a65-e5de20ed4567'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Que désigne le tempo en musculation ?', 'mcq', '["La charge de la barre","La vitesse de chaque phase du mouvement","Le rythme de la musique","La durée du repos après la séance"]'::jsonb, 1, 'Contrôler la descente, marquer une pause, remonter franchement : le tempo rend le geste plus propre et plus efficace.', 7),
    ('95adb443-d7c4-5035-934d-18cf8c04f2bf'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Au squat, quel point de technique est essentiel ?', 'mcq', '["Genoux qui rentrent vers l’intérieur","Talons qui décollent","Dos droit, genoux dans l’axe des pieds","Dos rond pour mieux descendre"]'::jsonb, 2, 'Un dos droit et des genoux alignés protègent la colonne et les articulations.', 8),
    ('d4b922f8-398c-5c75-9930-394fe7fc6af7'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'À 16-18 ans, on peut chercher sa charge maximale dès que possible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le squelette n’a pas fini de se solidifier : on monte les charges progressivement, sans chercher de maximum.', 9),
    ('6237c5e1-82ea-588d-bd22-47f1bac7649c'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Que fait-on si le dos s’arrondit sous la charge ?', 'mcq', '["On force pour finir la série","On ajoute du poids","On ferme les yeux","On repose la barre et on corrige la technique"]'::jsonb, 3, 'Le dos rond sous charge est un signal d’alerte : mieux vaut arrêter que de risquer le dos.', 10),
    ('eaaf79da-9e11-5a0f-a7b9-96751564dc51'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Une douleur vive dans une articulation est une simple fatigue musculaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La fatigue se ressent dans le muscle ; une douleur d’articulation est un signal d’alerte qui impose d’arrêter.', 11),
    ('036713ba-1bbe-59f9-acac-e587030b6cf3'::uuid, '6a03e846-f269-5c2a-9b6c-2e3312692675'::uuid, 'Combien de séances « corps entier » par semaine suffisent pour progresser, avec du repos entre chacune ?', 'mcq', '["Une tous les deux mois","Environ trois","Quinze","Aucune"]'::jsonb, 1, 'Trois séances par semaine avec un jour de repos entre chaque laissent le temps de récupérer et de progresser.', 12),
    ('75b7d943-2d0c-552b-973a-6f92caac4df1'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Quel nutriment est le carburant principal d’un effort intense ?', 'mcq', '["Le sel","Les glucides","Les protéines","Les fibres"]'::jsonb, 1, 'Les glucides sont brûlés le plus vite : c’est le carburant de l’intensité.', 1),
    ('3297e71e-8e4c-5b27-8fe8-c3d009f66570'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Quelle quantité de glucides un sportif régulier doit-il viser par kilo et par jour ?', 'mcq', '["20 g","50 g","0,5 g","5 à 7 g"]'::jsonb, 3, 'Cinq à sept grammes par kilo et par jour couvrent les besoins de l’entraînement régulier.', 2),
    ('1e2bb40a-0913-5853-b575-30b47bcd2a26'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Quel est le rôle principal des protéines pour un sportif ?', 'mcq', '["Hydrater le corps","Fournir l’énergie la plus rapide","Remplacer le sommeil","Réparer et construire les muscles"]'::jsonb, 3, 'Elles apportent les briques qui servent à réparer les fibres après l’effort.', 3),
    ('a136d4aa-36c0-5560-8b69-ae8e62c3f6eb'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Mieux vaut répartir les protéines sur la journée que tout manger en un seul repas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le corps utilise mieux les protéines en apports répartis, et l’assiette normale suffit à les apporter.', 4),
    ('d8761c4c-04f4-50d4-9fc1-0a1dcbac7afb'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Quelle perte de poids en eau suffit à faire baisser la performance ?', 'mcq', '["Environ 2 %","Environ 20 %","Environ 50 %","Aucune"]'::jsonb, 0, 'Dès 2 % du poids en eau perdus, la performance diminue : on boit avant d’avoir soif.', 5),
    ('2d43a3ea-87b7-5a4b-a4f5-7a8716ea1bc9'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Combien de temps avant l’effort prend-on un repas riche en glucides ?', 'mcq', '["Le lendemain","Environ trois heures","Deux minutes","Dix secondes"]'::jsonb, 1, 'Trois heures laissent le temps de digérer tout en ayant des réserves pleines.', 6),
    ('95e73f05-c363-539a-b156-5cceb1520fad'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'La « fenêtre anabolique » de 30 minutes est une obligation stricte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est moins stricte qu’on le dit : c’est l’apport total de la journée qui compte le plus.', 7),
    ('c78f2c27-7e6a-52d1-993f-e71cf6085ca2'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Que dit-on de la créatine pour un adolescent ?', 'mcq', '["Elle remplace l’entraînement","Elle est sans danger à tout âge sans réserve","Elle n’est pas conseillée avant 18 ans sans avis médical","Elle est obligatoire"]'::jsonb, 2, 'Efficace et étudiée chez l’adulte, elle n’est pas conseillée avant 18 ans sans avis médical.', 8),
    ('23c0956f-dec5-56e5-99a6-592b564d2790'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Que recommande l’ANSES à propos des boissons énergisantes pour les adolescents ?', 'mcq', '["En boire avant chaque match","En faire une boisson quotidienne","Les mélanger avec de l’alcool","Les déconseiller"]'::jsonb, 3, 'Ces boissons sont déconseillées aux adolescents, et la caféine n’est pas pour les mineurs.', 9),
    ('16145745-08b6-5c10-b65c-9c7bdb511bbd'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Faire un régime strict ou un jeûne est une bonne idée pendant la croissance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pendant la croissance, le corps a besoin d’énergie et de nutriments : on évite régimes et jeûne.', 10),
    ('10959fcf-95eb-5fe2-a31c-51d790739482'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'Pourquoi un complément alimentaire peut-il poser problème à un athlète ?', 'mcq', '["Il peut contenir des substances dopantes non indiquées","Il est toujours gratuit","Il rend invisible aux contrôles","Il est interdit de le manger"]'::jsonb, 0, 'Certains compléments contiennent des produits interdits : le contrôle positif « involontaire » reste un contrôle positif.', 11),
    ('05f355e5-e676-59f8-ace9-efa9b77e567a'::uuid, '68577df6-a34d-5efb-8243-20d9085a4424'::uuid, 'La veille d’un match, que choisir ?', 'mcq', '["Seulement une boisson énergisante","Pâtes, protéines, légumes et eau, sans nouveauté","Un aliment inconnu pour tester","Rien du tout"]'::jsonb, 1, 'Féculents et protéines habituels, sans essai de nouveauté : on ne teste jamais un aliment le jour J.', 12),
    ('fec77c98-0750-5dae-b439-a86c571be90d'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Quel tissu est touché lors d’une entorse ?', 'mcq', '["Un nerf","Un muscle uniquement","Un ligament","Un os"]'::jsonb, 2, 'Un ligament tient l’articulation ; l’entorse le met à rude épreuve, voire le rompt.', 1),
    ('d2e4d7e4-cf52-5745-b2ab-f7f429075894'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Combien de grades distingue-t-on pour une entorse ?', 'mcq', '["Trois","Sept","Un seul","Deux"]'::jsonb, 0, 'Du simple étirement à la rupture complète, on décrit trois grades.', 2),
    ('9b87d703-b818-5137-b7d8-92a28dd877ce'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Quelle articulation est la plus souvent touchée par les entorses ?', 'mcq', '["La cheville","Le coude","Le poignet","La nuque"]'::jsonb, 0, 'La cheville encaisse des appuis violents et des torsions : c’est l’entorse la plus fréquente.', 3),
    ('30b676c9-357d-5f3d-b220-b5ea2f44a55a'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Que mettent en avant les recommandations « PEACE & LOVE » après la phase initiale ?', 'mcq', '["Masser très fort","Remettre l’articulation en mouvement progressivement","Rester immobile pendant des mois","Forcer le plus vite possible"]'::jsonb, 1, 'Bouger peu à peu, sans douleur vive, aide l’articulation à guérir mieux que l’immobilité totale.', 4),
    ('f36d67e3-c49f-576f-947d-5a44fa909bec'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Une « tendinite » est en réalité le plus souvent…', 'mcq', '["Un os cassé","Un manque d’eau","Une tendinopathie de surcharge","Un microbe"]'::jsonb, 2, 'Le tendon a reçu trop d’effort trop vite : on adapte la charge et on renforce progressivement.', 5),
    ('c1b0d4a3-f41f-5d3e-9e32-c27ba098c1b9'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Quelle lésion musculaire est la plus grave ?', 'mcq', '["La contracture","La courbature","Le point de côté","La déchirure"]'::jsonb, 3, 'La déchirure est la rupture la plus étendue ; elle demande 6 semaines et plus.', 6),
    ('82e3efb7-97c6-5518-b295-f7ac6c84282c'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Après un choc à la tête avec confusion, le joueur doit finir le match s’il se sent mieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Au moindre doute, on sort : un second choc sur un cerveau fragilisé peut être grave.', 7),
    ('1f5bb047-4d81-5a75-96e5-308dac048a3a'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Parmi ces signes, lequel évoque une commotion ?', 'mcq', '["Mal de tête, confusion, nausée","Une crampe au mollet","Un hoquet","Une courbature"]'::jsonb, 0, 'Maux de tête, confusion, nausées et troubles de la vue sont les signes d’une commotion.', 8),
    ('365ba845-69d9-52ec-b831-eaf64ea6cbff'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Comment se fait le retour au sport après une commotion ?', 'mcq', '["Sans avis médical","Repos, puis reprise progressive par paliers","Directement en match","Par un sprint maximal"]'::jsonb, 1, 'Le cerveau a besoin de repos, puis d’une reprise graduée sur plusieurs semaines chez un mineur.', 9),
    ('f2df6ca7-777d-5db0-949d-fb4d4fbf4c39'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Une contracture dure en général environ…', 'mcq', '["Un jour exactement","Dix ans","Une semaine","Un an"]'::jsonb, 2, 'C’est la lésion musculaire la plus bénigne, d’environ une semaine à titre indicatif.', 10),
    ('0c5a7714-b4dc-56f6-869c-e637688953bf'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Une douleur qui persiste ou une articulation qui se bloque justifie de consulter un médecin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des signes d’alerte : on consulte au lieu de s’improviser soignant.', 11),
    ('1123b4e5-25be-523b-9960-aa42d013cc99'::uuid, '8ccdbaa0-982c-5665-999d-de1ac790c41f'::uuid, 'Quelle est la meilleure prévention des blessures ?', 'mcq', '["Ne jamais s’entraîner","Forcer chaque séance","Supprimer l’échauffement","Échauffement, progressivité, renforcement et sommeil"]'::jsonb, 3, 'Un corps préparé, progressivement entraîné et reposé encaisse beaucoup mieux les efforts.', 12),
    ('694c275b-172e-544e-bff2-04c10d952cd8'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Dans quel pays est né le sport moderne au XIXe siècle ?', 'mcq', '["L’Angleterre","La France","L’Italie","Les États-Unis"]'::jsonb, 0, 'Dans les public schools et les clubs anglais, on a codifié les jeux : des règles écrites, les mêmes pour tous.', 1),
    ('e1f81bd4-fc67-5505-ae6a-50ce7190388d'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'En quelle année la Football Association a-t-elle été créée ?', 'mcq', '["1998","1863","1763","1913"]'::jsonb, 1, 'En 1863, elle fixe les premières règles communes du football ; la Rugby Football Union suivra en 1871.', 2),
    ('a7822dec-8a2a-5a7e-9eed-9759761ffe82'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Quel tournoi de tennis débute en 1877 ?', 'mcq', '["Les Jeux olympiques","Le Tour de France","Wimbledon","Roland-Garros"]'::jsonb, 2, 'Le lawn-tennis est breveté en 1874, et Wimbledon organise son premier tournoi en 1877.', 3),
    ('b849a330-a2c4-5490-bafd-a755fecad022'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Un sportif « amateur » est un sportif…', 'mcq', '["payé pour jouer","qui ne s’entraîne jamais","étranger","qui joue par plaisir, sans être payé"]'::jsonb, 3, 'Au XIXe siècle, les amateurs s’opposent aux professionnels, payés pour jouer.', 4),
    ('2a1c43e4-bb5c-5f77-a79e-19d6832902fd'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Quel club est fondé au Havre en 1872 ?', 'mcq', '["Le Havre Athletic Club","Le Stade français","Le Racing Club de France","Le Paris Saint-Germain"]'::jsonb, 0, 'Le Havre AC, créé en 1872, est l’un des premiers clubs à introduire le sport anglais en France.', 5),
    ('c83c0b9f-90e0-536f-8f00-3f63b47958c5'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Qui a apporté les premiers sports modernes en France ?', 'mcq', '["Aucun étranger","Des Anglais installés en France","Des Espagnols","Des Japonais"]'::jsonb, 1, 'Ce sont des Anglais installés en France qui ont apporté leurs jeux et fondé les premiers clubs.', 6),
    ('79b648e1-77aa-5733-b1d7-6b44534947ef'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Avant le sport, quelle pratique domine à l’école en France ?', 'mcq', '["Le tennis","L’escalade","La gymnastique, inspirée du Turnen allemand","Le rugby"]'::jsonb, 2, 'La gymnastique et les bataillons scolaires devaient former des corps forts avant l’arrivée du sport.', 7),
    ('2e4444be-6f36-5b4b-a0f2-8958b8a9c05e'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Quelle loi permet de créer librement des associations sportives ?', 'mcq', '["La loi de 1789","La loi de 1936","La loi de 2024","La loi de 1901"]'::jsonb, 3, 'La loi de 1901 donne à tous le droit de fonder une association : les clubs se multiplient.', 8),
    ('689281cf-df89-50dc-adbf-31e935ad8c47'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Léo Lagrange est associé…', 'mcq', '["au sport pour tous sous le Front populaire en 1936","à la création du football en 1863","au tennis de 1877","au dopage"]'::jsonb, 0, 'Avec les congés payés, il incarne en 1936 l’idée que le sport et les loisirs sont pour tous.', 9),
    ('0484d91b-2931-5474-ab5e-925e30eb2ef0'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Le sport moderne est né sans aucune règle écrite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : le sport moderne naît de la codification, c’est-à-dire des règles écrites communes à tous.', 10),
    ('24a450a1-1087-5283-8f29-6421f7a7fa98'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'Le Racing Club de France est créé en 1882.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des premiers clubs français, avec le Havre AC (1872) et le Stade français (1883).', 11),
    ('9a2bff6d-552d-5541-863f-b90ff5c1c00e'::uuid, 'b26a51b6-e9cf-5ccc-ac38-6b8f7da083d4'::uuid, 'En France, l’UNSS organise…', 'mcq', '["les transferts de joueurs","le sport scolaire","le Tour de France","les Jeux olympiques"]'::jsonb, 1, 'L’UNSS propose des compétitions entre établissements : c’est le sport scolaire.', 12),
    ('9def67c7-1f87-5a45-bf3a-265acb14689a'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Combien de médailles d’or Jesse Owens a-t-il gagnées à Berlin en 1936 ?', 'mcq', '["Dix","Aucune","Quatre","Une"]'::jsonb, 2, 'Ses quatre ors dans l’Allemagne nazie ont contredit le discours de propagande sur la supériorité raciale.', 1),
    ('acb04d28-22b0-543e-9c9d-99c5ca17dfd7'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Qui filme les Jeux de Berlin pour le régime nazi ?', 'mcq', '["Alice Milliat","Léo Lagrange","Pierre de Coubertin","Leni Riefenstahl"]'::jsonb, 3, 'La cinéaste Leni Riefenstahl a mis en images les Jeux de 1936.', 2),
    ('ee3ff776-c34d-5aac-88b5-e14ec6eb218a'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Quel geste Tommie Smith et John Carlos font-ils à Mexico en 1968 ?', 'mcq', '["Ils lèvent le poing ganté de noir","Ils s’agenouillent","Ils quittent le stade","Ils chantent"]'::jsonb, 0, 'Le 16 octobre 1968, poing levé, ils dénoncent le sort des Noirs américains.', 3),
    ('57a8c8b7-385a-5aca-b221-20f77210ce51'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Qui est Peter Norman ?', 'mcq', '["Un dirigeant du CIO","L’Australien deuxième du 200 m, solidaire du geste","Un arbitre","Un entraîneur américain"]'::jsonb, 1, 'Il se montre solidaire des deux Américains sur le podium.', 4),
    ('abe7bbc3-a4c5-5076-bfab-3e679e073f8e'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Quelle équipe est attaquée aux Jeux de Munich en 1972 ?', 'mcq', '["L’équipe de Chine","L’équipe d’Italie","L’équipe d’Israël","L’équipe de France"]'::jsonb, 2, 'Onze membres de la délégation israélienne sont tués lors de cet attentat.', 5),
    ('97d7bd6e-bf8a-54dc-8d2f-df4af600759b'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Pourquoi les Jeux de Moscou en 1980 sont-ils boycottés par une soixantaine de pays ?', 'mcq', '["À cause d’une grève","À cause de la météo","À cause d’un virus","À cause de l’invasion de l’Afghanistan par l’URSS"]'::jsonb, 3, 'C’est une réaction politique à l’invasion soviétique de l’Afghanistan.', 6),
    ('8d86bd0f-e0c0-5352-baf5-143ccda4a612'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Qui boycotte les Jeux de Los Angeles en 1984 ?', 'mcq', '["L’URSS et ses alliés","Les États-Unis","La France","Le Japon"]'::jsonb, 0, 'Les Soviétiques répondent au boycott de 1980 : c’est la logique de la guerre froide.', 7),
    ('76757bac-e9d3-5adb-b546-e56ace2a7cc6'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'L’Afrique du Sud, pays de l’apartheid, a été exclue des Jeux de…', 'mcq', '["1936 à 1948","1964 à 1992","1900 à 1924","2000 à 2010"]'::jsonb, 1, 'Le sport a servi de moyen de pression contre l’apartheid.', 8),
    ('bd15c7ea-89ed-5d06-9473-7c1f49e95584'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Qu’appelle-t-on la « diplomatie du ping-pong » ?', 'mcq', '["Un boycott","Un attentat","Le rapprochement États-Unis–Chine en 1971","Un traité sur le tennis"]'::jsonb, 2, 'Des joueurs de tennis de table ont servi de messagers entre les deux pays en 1971.', 9),
    ('718d946d-0ad0-57ff-b661-a28c4abb7c2b'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Le sport est toujours neutre et sans lien avec la politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’histoire montre l’inverse : propagande, boycotts, gestes de protestation… le sport n’est jamais neutre.', 10),
    ('fc7546db-5b7e-5ba5-ac8b-acc10eb2a29e'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'Depuis 2022, quel pays est suspendu des compétitions internationales avec des athlètes « neutres » à Paris 2024 ?', 'mcq', '["La Belgique","Le Canada","L’Espagne","La Russie"]'::jsonb, 3, 'Les athlètes russes ne concourent pas sous leur drapeau : ils sont « neutres » à Paris 2024.', 11),
    ('2020d0e4-c4e5-5edb-bfda-d827daa7fd20'::uuid, '19a82831-911c-5324-adc5-d575f757f420'::uuid, 'La Coupe du monde 2022 au Qatar a relancé le débat sur…', 'mcq', '["les droits humains","le prix des billets d’avion","la météo","le nombre de buts"]'::jsonb, 0, 'Les conditions de travail et les libertés au Qatar ont nourri la critique de l’événement.', 12),
    ('c89f758e-e722-553d-a352-e1a6a0e5a0ed'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Combien de femmes participent aux Jeux de Paris en 1900 ?', 'mcq', '["Aucune","22","2 000","220"]'::jsonb, 1, 'Elles sont vingt-deux : les femmes entrent aux Jeux, mais en très petit nombre.', 1),
    ('88abd0b3-ae16-5744-b0fd-bd7a2fcb518b'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Quelle sportive gagne le tournoi de tennis des Jeux de 1900 ?', 'mcq', '["Joan Benoit","Billie Jean King","Charlotte Cooper","Alice Milliat"]'::jsonb, 2, 'Charlotte Cooper, en tennis, est l’une des premières championnes olympiques.', 2),
    ('8e4477be-711c-5d6b-9ab5-00ef4911ab2d'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Qui fonde la FSFI en 1921 ?', 'mcq', '["Pierre de Coubertin","Léo Lagrange","Joan Benoit","Alice Milliat"]'::jsonb, 3, 'Alice Milliat crée la Fédération sportive féminine internationale face au refus de Coubertin.', 3),
    ('141050e3-1f0c-5ab3-9e99-d724b170805d'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Où ont lieu les premiers Jeux mondiaux féminins en 1922 ?', 'mcq', '["À Paris","À Londres","À Berlin","À New York"]'::jsonb, 0, 'Paris accueille ces Jeux organisés par Alice Milliat et la FSFI.', 4),
    ('097f6ce7-e85b-5d0a-80f4-87e042f65430'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Quel est le point de vue de Coubertin sur les femmes aux Jeux ?', 'mcq', '["Il les choisit lui-même","Il y est hostile","Il les encourage fortement","Il en est indifférent"]'::jsonb, 1, 'Coubertin refuse leur présence, ce qui pousse Alice Milliat à créer ses propres Jeux.', 5),
    ('7d5991d8-388d-5a85-8ea0-37ddbf80efa9'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Après son entrée aux Jeux en 1928, quelle épreuve féminine est retirée jusqu’en 1960 ?', 'mcq', '["Le relais","Le tennis","Le 800 m","Le saut en longueur"]'::jsonb, 2, 'On a jugé le 800 m « trop dur » pour les femmes, un préjugé sans fondement.', 6),
    ('712c2070-5d78-5eaf-8f46-916374d98f1c'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Que fait Kathrine Switzer en 1967 ?', 'mcq', '["Elle gagne Wimbledon","Elle remporte l’or à Paris","Elle fonde la FSFI","Elle court le marathon de Boston avec un dossard"]'::jsonb, 3, 'Elle court le marathon de Boston avec un dossard, à une époque où cela ne se faisait pas.', 7),
    ('343149b5-e6a5-5f94-86c3-670b00ac7596'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Qui bat Bobby Riggs en 1973 lors de la « bataille des sexes » ?', 'mcq', '["Billie Jean King","Joan Benoit","Clarisse Agbegnenou","Wendie Renard"]'::jsonb, 0, 'La victoire de Billie Jean King devient un symbole mondial de l’égalité.', 8),
    ('b9212ed9-0ba7-5848-bc77-bbe75bf99b0c'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Qui gagne le premier marathon olympique féminin en 1984 ?', 'mcq', '["Amandine Henry","Joan Benoit","Kathrine Switzer","Alice Milliat"]'::jsonb, 1, 'Joan Benoit remporte le premier marathon olympique féminin, dix-sept ans après Boston 1967.', 9),
    ('ee24e368-1fd0-59bd-a167-fa7d0bb41be2'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Les Jeux de Paris 2024 sont les premiers à atteindre la parité hommes-femmes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il y a autant d’athlètes femmes que d’hommes : une première dans l’histoire des Jeux.', 10),
    ('e099998e-bd04-5bc2-81ad-4e2c15fa79c4'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'La parité aux Jeux signifie que tout est égal dans le sport.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La médiatisation, les primes et la présence de dirigeantes restent inégales.', 11),
    ('4f184d9b-0916-5413-b58d-76d1d66ec1f7'::uuid, '5f3b7a08-7467-5298-9774-be5fdc725b40'::uuid, 'Comment s’appelle le championnat féminin de football devenu professionnel en France en 2024 ?', 'mcq', '["La Coupe du monde","Le Top 14","La Première Ligue","La Ligue des champions"]'::jsonb, 2, 'La Première Ligue marque la professionnalisation du football féminin français.', 12),
    ('ff6a8cdc-6bd0-5652-82c5-a1d0504aaf29'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Quelle est la principale source d’argent d’un championnat de football ?', 'mcq', '["La vente de ballons","Les cours de sport","Les amendes","Les droits de télévision"]'::jsonb, 3, 'Les chaînes paient très cher pour diffuser les matchs : c’est une ressource majeure.', 1),
    ('7fa84255-cc9a-5f55-9a6c-da3e936b6525'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Quelle chaîne a fait faillite en 2020 en laissant la Ligue 1 sans diffuseur ?', 'mcq', '["Mediapro","DAZN","Ligue 1+","Canal+"]'::jsonb, 0, 'La faillite de Mediapro en 2020 a fragilisé les finances de la Ligue 1.', 2),
    ('83afb22e-b957-5efa-a107-0cfb8d738499'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Quelle chaîne la Ligue a-t-elle lancée elle-même en 2025 ?', 'mcq', '["Eurosport","Ligue 1+","DAZN","Mediapro"]'::jsonb, 1, 'Après DAZN en 2024-25, la Ligue crée sa propre chaîne, Ligue 1+.', 3),
    ('b824402a-c405-58ca-b675-d4b693f15ab0'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Quel joueur détient le record de transfert, 222 millions d’euros en 2017 ?', 'mcq', '["Mbappé","Messi","Neymar","Zidane"]'::jsonb, 2, 'Neymar a été acheté par le PSG pour 222 millions d’euros en 2017.', 4),
    ('0a99497d-a9df-5e42-ab98-60fc7ac22c7e'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Depuis quelle année le PSG appartient-il au Qatar ?', 'mcq', '["1970","1999","2024","2011"]'::jsonb, 3, 'Depuis 2011, des investisseurs qataris détiennent le club.', 5),
    ('b390ff9b-8c95-5c5f-a73c-ca54a8e39b5f'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'À quoi servent les règles de « durabilité financière » de l’UEFA ?', 'mcq', '["Éviter qu’un club dépense durablement plus qu’il ne gagne","Fixer le prix des billets","Choisir les arbitres","Interdire les sponsors"]'::jsonb, 0, 'Elles limitent les déficits et l’avantage des propriétaires trop riches.', 6),
    ('ab9d4055-609f-5366-ba2d-f46560e4671c'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'La Premier League anglaise tire des droits TV bien plus élevés que la Ligue 1.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Son marché est beaucoup plus riche : ses droits TV rapportent bien davantage.', 7),
    ('97e6ed58-4efc-5515-93b0-1c856b48c327'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Qui finance surtout le comité d’organisation de Paris 2024 ?', 'mcq', '["Aucune entreprise","Le privé","Uniquement les impôts locaux","Les spectateurs seuls"]'::jsonb, 1, 'Le budget d’environ 4,4 milliards d’euros du comité vient surtout de ressources privées.', 8),
    ('c1371350-f962-5b84-bb7f-6db2078ea9bc'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Le coût public des Jeux de Paris 2024 est connu avec une précision parfaite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des estimations, comme celle de la Cour des comptes en 2025 : elles se discutent.', 9),
    ('35754e1c-6e1b-5c52-a5f9-fe16ddab13d8'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Tous les sportifs gagnent des fortunes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les écarts sont immenses : la majorité des sportifs ne vivent pas de leur sport.', 10),
    ('f3826f25-5cc7-58ea-bd35-2324cd6035cc'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Quelles marques sont des équipementiers célèbres ?', 'mcq', '["Apple et Google","Danone et Nestlé","Nike et Adidas","Michelin et Renault"]'::jsonb, 2, 'Elles fabriquent les maillots et les chaussures et sponsorisent clubs et athlètes.', 11),
    ('3d52213c-3a01-54b2-bdb4-b89d3bdb6113'::uuid, '9aff615d-9bf8-5286-9a80-6c50df69b5dd'::uuid, 'Que désigne l’e-sport ?', 'mcq', '["Le sport en extérieur","Le sport électrique","Un régime alimentaire","Les compétitions de jeux vidéo"]'::jsonb, 3, 'C’est une compétition de jeux vidéo, aussi en plein essor économique.', 12),
    ('79858160-d75c-534a-babc-3d3acfa630ac'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Que désigne le dopage ?', 'mcq', '["L’usage de substances ou de méthodes interdites pour améliorer ses performances","Un régime alimentaire","Un type d’entraînement","Une blessure"]'::jsonb, 0, 'C’est de la triche et un danger pour la santé : la liste des produits interdits est mise à jour chaque année.', 1),
    ('34fb4dee-d3e4-50bc-a390-1eff1431822a'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Quel coureur meurt sur le Mont Ventoux en 1967 ?', 'mcq', '["Willy Voet","Tom Simpson","Lance Armstrong","Ben Johnson"]'::jsonb, 1, 'La mort de Tom Simpson a marqué les esprits et relancé le débat sur le dopage.', 2),
    ('246e87e7-3f75-5f36-900f-1a78f06435ed'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Quel sprinter est déclassé après les Jeux de Séoul en 1988 ?', 'mcq', '["Usain Bolt","Carl Lewis","Ben Johnson","Jesse Owens"]'::jsonb, 2, 'Ben Johnson perd son titre sur 100 m à cause d’un contrôle positif.', 3),
    ('444ff98f-5157-53b2-9449-3af40ee2fd5a'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Quelle affaire éclate pendant le Tour de France 1998 ?', 'mcq', '["L’affaire Mediapro","L’affaire Milliat","L’affaire Lagrange","L’affaire Festina"]'::jsonb, 3, 'Willy Voet, soigneur de Festina, est arrêté avec des produits dopants dans sa voiture.', 4),
    ('42e2b523-a8ea-5ebd-af7a-84ac049d2015'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Qu’est-il arrivé à Lance Armstrong en 2012 ?', 'mcq', '["Il a été déchu de ses titres","Il a reçu un trophée","Il a pris sa retraite avec les honneurs","Il a battu un record"]'::jsonb, 0, 'Ses victoires lui ont été retirées après les révélations sur le dopage.', 5),
    ('8f429c3f-9d75-5b10-9fa8-5f25183244ce'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Que révèle le rapport McLaren en 2016 ?', 'mcq', '["Une fraude de billetterie","Un dopage d’État en Russie","Un tournoi de tennis","Un record du monde"]'::jsonb, 1, 'Il met en évidence un système de dopage organisé par l’État russe.', 6),
    ('277e1b6b-2800-5b0d-b250-8d38874e92fb'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'En quelle année est créée l’Agence mondiale antidopage (AMA) ?', 'mcq', '["2020","1945","1999","1899"]'::jsonb, 2, 'L’AMA naît en 1999 ; son siège est à Montréal.', 7),
    ('d4075b09-86ac-5c49-91be-4d8570227eeb'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Que fait le passeport biologique ?', 'mcq', '["Il donne le droit de voyager","Il vérifie le casier judiciaire","Il remplace le contrôle urinaire","Il suit les valeurs sanguines de l’athlète dans le temps"]'::jsonb, 3, 'En observant l’évolution du sang, il repère des anomalies même sans produit détecté.', 8),
    ('2747c831-1278-53f0-940c-4eec1f7aa139'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Quelle est la sanction habituelle d’un dopage en principe ?', 'mcq', '["4 ans de suspension","1 jour","Un simple avertissement","Aucune sanction"]'::jsonb, 0, 'Quatre ans en principe, ce qui peut mettre fin à une carrière.', 9),
    ('daf6eb51-48cd-5259-b89f-02806483da7b'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Que permet une AUT ?', 'mcq', '["Gagner une médaille","Prendre légalement un médicament interdit pour une raison médicale","Se doper sans contrôle","Ne jamais être testé"]'::jsonb, 1, 'L’autorisation à usage thérapeutique est la seule dérogation légale, après examen médical.', 10),
    ('b4ba5795-8101-50fb-a30a-26822edeb7f1'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'L’EPO épaissit le sang et fait courir un risque cardiaque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un sang plus épais gêne la circulation et peut provoquer des accidents cardiaques.', 11),
    ('32381b30-7df3-57b6-b8f0-bc8e2c1b2da2'::uuid, 'ddefec65-364c-5c40-a547-813b98504e84'::uuid, 'Si un complément alimentaire contenait un produit interdit à l’insu du sportif, celui-ci n’est pas responsable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’athlète est toujours responsable de ce qu’il avale : « je ne savais pas » ne protège pas.', 12),
    ('9f76f5ff-6bca-5fa6-9056-8fa0d18ea7bb'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Quelle molécule le muscle utilise-t-il directement pour se contracter ?', 'mcq', '["L’oxygène","L’ATP","Le lactate","Le glucose seul"]'::jsonb, 1, 'Le muscle ne sait dépenser que de l’ATP ; toutes les filières servent à en refabriquer.', 1),
    ('fb81c6b9-d97b-5325-8c02-e0c7504da312'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Combien de filières énergétiques le corps utilise-t-il pour refabriquer l’ATP ?', 'mcq', '["Trois","Cinq","Une seule","Deux"]'::jsonb, 0, 'Il y en a trois : alactique, lactique et aérobie, qui se chevauchent en permanence.', 2),
    ('091f57b2-bdd1-5611-820a-836695438a60'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Quelle filière domine pendant un sprint de 100 m ?', 'mcq', '["L’anaérobie lactique","L’anaérobie alactique","Aucune, le corps se repose","L’aérobie"]'::jsonb, 1, 'Sur les premières secondes, la phosphocréatine déjà stockée fournit l’énergie : c’est très puissant mais ça ne dure qu’une dizaine de secondes.', 3),
    ('76b429e2-b3ca-5a88-a2d6-c91b216af10f'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Un 400 m ou un 100 m nage sollicite surtout la filière anaérobie lactique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Entre environ 10 secondes et 2 minutes, la glycolyse sans oxygène domine : c’est la zone du 400 m et du 100 m nage.', 4),
    ('a1155d0b-5cba-5f29-91e2-c087e5b2ac65'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Quelle filière est « inépuisable » mais moins puissante ?', 'mcq', '["L’alactique","L’aérobie","La lactique","Aucune"]'::jsonb, 1, 'Avec l’oxygène, glucides et lipides peuvent être brûlés longtemps, mais plus lentement : idéal pour le 10 km et le marathon.', 5),
    ('9bdbdae0-a65f-5964-a8f1-43188dbdda94'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Le lactate est un poison qui provoque les courbatures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le lactate est un carburant recyclé par le cœur, les muscles et le foie ; les courbatures viennent de micro-lésions des fibres.', 6),
    ('ff6912e9-9443-5e7f-900a-71a9a8dd641d'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Comment entraîne-t-on surtout la filière alactique ?', 'mcq', '["Des étirements","De longues sorties à allure lente","Des efforts très courts et maximaux, avec récupération complète","Des séries de 10 minutes sans repos"]'::jsonb, 2, 'Le stock de phosphocréatine ne se reconstitue qu’au repos : il faut récupérer complètement entre deux efforts pour rester explosif.', 7),
    ('be15ce59-7957-5170-9953-8f6b6c2333c3'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Pour entraîner la filière lactique, on utilise plutôt…', 'mcq', '["Des séries de 30 secondes à 2 minutes à forte intensité","Des siestes","Des sprints de 3 secondes","Une marche tranquille d’une heure"]'::jsonb, 0, 'C’est la durée où la glycolyse domine : des séries de 30 s à 2 min en poussant fort la sollicitent directement.', 8),
    ('fd21e5f1-de9f-5bb6-8f4f-2d8426f9e8eb'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Pendant un marathon, quelle filière fournit presque toute l’énergie ?', 'mcq', '["La phosphocréatine seule","La lactique seule","L’aérobie","L’alactique"]'::jsonb, 2, 'Sur plusieurs heures, seule la filière aérobie peut suivre : elle brûle glucides puis lipides avec de l’oxygène.', 9),
    ('c51d0583-6f99-50d4-a7af-a28f205ade57'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Les trois filières s’allument l’une après l’autre, jamais en même temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles tournent toujours ensemble ; c’est l’intensité et la durée qui décident de celle qui domine.', 10),
    ('f6bc0e4c-49ac-531c-9826-f3ec94eb9645'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Que signifie « anaérobie » ?', 'mcq', '["Avec beaucoup d’oxygène","Sans oxygène","Sans sucre","Sans effort"]'::jsonb, 1, 'Les filières anaérobies produisent l’ATP sans oxygène : c’est immédiat et puissant, mais ça s’épuise vite.', 11),
    ('98620af7-d583-50e8-8d59-40b72a4c650a'::uuid, '35223267-dc74-5199-b08f-881cd2af6b40'::uuid, 'Pourquoi un footballeur doit-il entraîner les trois filières ?', 'mcq', '["Il enchaîne démarrages, efforts intenses et récupérations pendant tout le match","Il ne court jamais vite","Il n’utilise que l’aérobie","Les filières n’existent pas en football"]'::jsonb, 0, 'Un match mêle explosivité, séquences intenses et un moteur aérobie qui récupère vite entre les actions.', 12),
    ('3d2b8b71-6b21-5c8b-9f87-2b9d3b2d3566'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Que désigne le « volume » d’un entraînement ?', 'mcq', '["Le nombre de jours de repos","La quantité de travail : durée, distance, répétitions","La difficulté de l’effort","Le bruit de la musique"]'::jsonb, 1, 'Le volume mesure la quantité faite ; la difficulté, c’est l’intensité.', 1),
    ('67c0e132-2010-51d0-8c99-bb38e4551430'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Que signifient les lettres de FITT ?', 'mcq', '["Fréquence, Intensité, Temps, Type","Fatigue, Inertie, Travail, Tension","Fitness, Initiation, Tests, Terrain","Force, Impact, Technique, Tempo"]'::jsonb, 0, 'FITT rappelle les quatre questions à se poser : combien de fois, à quelle difficulté, combien de temps, quel type d’exercice.', 2),
    ('7bf1aa05-1f0a-5a73-a1d7-19eb53ac9305'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'De combien peut-on augmenter la charge de travail chaque semaine, environ ?', 'mcq', '["100 %","50 %","10 %","0 %"]'::jsonb, 2, 'Environ 10 % par semaine : assez pour progresser, assez peu pour que le corps s’adapte sans se blesser.', 3),
    ('d1795b66-676f-52f1-bd4c-4264a339f25c'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Pour progresser vite, il vaut mieux changer tous les réglages à la fois.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne modifie qu’un réglage à la fois : sinon on ne sait plus ce qui marche, et le corps encaisse mal.', 4),
    ('8e6bd410-f42e-51b8-93bc-0c8386a3a93c'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Que dit le principe de spécificité ?', 'mcq', '["Il ne faut jamais changer d’exercice","Tous les sports se valent","On progresse dans ce qu’on travaille","Il faut s’entraîner seul"]'::jsonb, 2, 'Courir améliore la course, pas la natation : l’entraînement doit ressembler à ce qu’on veut améliorer.', 5),
    ('b7129606-cd27-5518-a4ba-9fb392f63d6d'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Après combien de temps d’arrêt les acquis commencent-ils à redescendre ?', 'mcq', '["Après 2 ans","Environ 2 à 3 semaines","Après 24 heures","Jamais"]'::jsonb, 1, 'C’est la réversibilité : sans entraînement, le corps perd ses adaptations en quelques semaines.', 6),
    ('5d7440f6-e35a-55b3-b8c2-d884c9e35dbb'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Où se fait réellement le progrès ?', 'mcq', '["Pendant la récupération, après la séance","Pendant les repas seulement","Nulle part, tout est inné","Uniquement pendant la séance"]'::jsonb, 0, 'La séance donne le signal, mais c’est au repos que le corps se reconstruit plus solide.', 7),
    ('cd14b22c-6e60-5280-9b41-f18a93d619f4'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Quel est l’intérêt d’un carnet d’entraînement ?', 'mcq', '["Impressionner ses amis","Remplacer la séance","Voir ce qui marche et repérer les signes de fatigue","Compter les calories des autres"]'::jsonb, 2, 'En notant séance, ressenti et fréquence cardiaque, on repère les tendances et on ajuste le programme.', 8),
    ('a8501e59-912e-5cee-b4b1-ffa949cceab6'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Un sportif fatigué en permanence, qui stagne et dort mal doit forcer davantage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les signes du surentraînement : la bonne réponse est de lever le pied quelques jours.', 9),
    ('3507b000-6583-559f-b01c-2848f231211c'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Que mesure l’« intensité » d’une séance ?', 'mcq', '["La difficulté de l’effort, par exemple en % de la VMA","La durée de la séance","Le prix du matériel","Le nombre de spectateurs"]'::jsonb, 0, 'L’intensité se règle en pourcentage de la VMA, de la charge maximale ou de la fréquence cardiaque maximale.', 10),
    ('db46f7b9-5a7e-5b6f-9c0b-60ba751a3509'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Pourquoi varier les exercices au fil du programme ?', 'mcq', '["Pour perdre du temps","Pour supprimer la récupération","Pour changer de club","Pour éviter l’ennui et les blessures de répétition"]'::jsonb, 3, 'C’est le principe de variété : changer les gestes ménage les articulations et garde la motivation.', 11),
    ('c9ff31fc-8596-56f5-a440-6afafa83909b'::uuid, 'cde88218-428d-5d01-b866-3834f4f5b447'::uuid, 'Le programme d’un autre sportif convient forcément à tout le monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’individualisation impose d’adapter le programme à son âge, son niveau, son objectif et son sommeil.', 12),
    ('cfa55cc3-859a-5e32-ac31-58baf0bac61d'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Pour développer la force maximale, quelle fourchette de répétitions vise-t-on ?', 'mcq', '["6 à 12","15 à 30","50 et plus","1 à 5"]'::jsonb, 3, 'Une charge très lourde ne se soulève que peu de fois : la force maximale se travaille entre 1 et 5 répétitions.', 1),
    ('760361d5-5a67-51e2-9641-a0c5c714f8cd'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Quelle fourchette de répétitions correspond à l’hypertrophie ?', 'mcq', '["1 à 3","6 à 12","30 à 50","Un nombre quelconque"]'::jsonb, 1, 'Entre 6 et 12 répétitions à 65-85 % du max : assez de tension pour faire grossir le muscle.', 2),
    ('16e4984a-05cf-51c0-b161-4029e21aaa4b'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'La puissance, c’est…', 'mcq', '["La taille du muscle","La force multipliée par la vitesse","La force seule","L’endurance multipliée par la durée"]'::jsonb, 1, 'Être puissant, c’est savoir produire de la force vite : un athlète fort mais lent manque de puissance.', 3),
    ('b18dbbbc-49d7-5b68-a05d-76c86632991c'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Comment travaille-t-on surtout la puissance ?', 'mcq', '["Séries de 50 répétitions","Étirements prolongés","Charges moyennes soulevées vite et pliométrie","Charges maximales très lentes"]'::jsonb, 2, 'Il faut associer force et vitesse : charges moyennes mouvées rapidement, sauts et lancers.', 4),
    ('579ca7e3-6bf4-598d-ba39-a469ecfc4cdf'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Un lycéen soulève 60 kg pour 10 répétitions. Quel est son max estimé avec la formule d’Epley ?', 'mcq', '["Environ 80 kg","Environ 100 kg","Environ 60 kg","Environ 70 kg"]'::jsonb, 0, 'Epley : 60 × (1 + 10 / 30) = 60 × 1,33, soit environ 80 kg.', 5),
    ('dea8484f-e2bd-5271-aad7-ad9da8036885'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Pourquoi estime-t-on son max plutôt que de le tester ?', 'mcq', '["Pour éviter le risque d’une répétition maximale","Parce que ça ne sert à rien","Parce que le max n’existe pas","Pour soulever plus lourd"]'::jsonb, 0, 'Tester un maximum, surtout sans pareur, expose aux blessures ; la formule donne un repère sûr.', 6),
    ('602be323-7248-5718-a58d-d16f84ae5122'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Que désigne le tempo en musculation ?', 'mcq', '["La charge de la barre","La vitesse de chaque phase du mouvement","Le rythme de la musique","La durée du repos après la séance"]'::jsonb, 1, 'Contrôler la descente, marquer une pause, remonter franchement : le tempo rend le geste plus propre et plus efficace.', 7),
    ('0e06da7c-edfe-596c-8d03-c12f420139d5'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Au squat, quel point de technique est essentiel ?', 'mcq', '["Genoux qui rentrent vers l’intérieur","Talons qui décollent","Dos droit, genoux dans l’axe des pieds","Dos rond pour mieux descendre"]'::jsonb, 2, 'Un dos droit et des genoux alignés protègent la colonne et les articulations.', 8),
    ('bce22508-90b5-5c01-855a-2e96e5c03951'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'À 16-18 ans, on peut chercher sa charge maximale dès que possible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le squelette n’a pas fini de se solidifier : on monte les charges progressivement, sans chercher de maximum.', 9),
    ('c65b060f-316d-597d-b069-d4fffa9c480b'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Que fait-on si le dos s’arrondit sous la charge ?', 'mcq', '["On force pour finir la série","On ajoute du poids","On ferme les yeux","On repose la barre et on corrige la technique"]'::jsonb, 3, 'Le dos rond sous charge est un signal d’alerte : mieux vaut arrêter que de risquer le dos.', 10),
    ('78a461f8-76ca-503f-ba59-073b6688be78'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Une douleur vive dans une articulation est une simple fatigue musculaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La fatigue se ressent dans le muscle ; une douleur d’articulation est un signal d’alerte qui impose d’arrêter.', 11),
    ('e0869495-8b60-5d42-9e43-a8f5aaeb17bb'::uuid, 'f93c9455-543c-5e75-9998-28b7c4442edd'::uuid, 'Combien de séances « corps entier » par semaine suffisent pour progresser, avec du repos entre chacune ?', 'mcq', '["Une tous les deux mois","Environ trois","Quinze","Aucune"]'::jsonb, 1, 'Trois séances par semaine avec un jour de repos entre chaque laissent le temps de récupérer et de progresser.', 12),
    ('8f386f00-f15f-566f-8f76-0ac2bbd0442d'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Quel nutriment est le carburant principal d’un effort intense ?', 'mcq', '["Le sel","Les glucides","Les protéines","Les fibres"]'::jsonb, 1, 'Les glucides sont brûlés le plus vite : c’est le carburant de l’intensité.', 1),
    ('74b5a22c-f2ee-5c5c-8597-dae9dc2e4351'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Quelle quantité de glucides un sportif régulier doit-il viser par kilo et par jour ?', 'mcq', '["20 g","50 g","0,5 g","5 à 7 g"]'::jsonb, 3, 'Cinq à sept grammes par kilo et par jour couvrent les besoins de l’entraînement régulier.', 2),
    ('93e9007e-f380-5000-99ac-3e543f07fdc3'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Quel est le rôle principal des protéines pour un sportif ?', 'mcq', '["Hydrater le corps","Fournir l’énergie la plus rapide","Remplacer le sommeil","Réparer et construire les muscles"]'::jsonb, 3, 'Elles apportent les briques qui servent à réparer les fibres après l’effort.', 3),
    ('335d323e-bb53-541b-8baf-16a4b6f951a3'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Mieux vaut répartir les protéines sur la journée que tout manger en un seul repas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le corps utilise mieux les protéines en apports répartis, et l’assiette normale suffit à les apporter.', 4),
    ('8e5bdeeb-e8f0-5ead-b140-2dbf8e619d83'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Quelle perte de poids en eau suffit à faire baisser la performance ?', 'mcq', '["Environ 2 %","Environ 20 %","Environ 50 %","Aucune"]'::jsonb, 0, 'Dès 2 % du poids en eau perdus, la performance diminue : on boit avant d’avoir soif.', 5),
    ('9a804559-3745-5bf3-8fca-f9f43592f2a6'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Combien de temps avant l’effort prend-on un repas riche en glucides ?', 'mcq', '["Le lendemain","Environ trois heures","Deux minutes","Dix secondes"]'::jsonb, 1, 'Trois heures laissent le temps de digérer tout en ayant des réserves pleines.', 6),
    ('f7a4a767-a9cc-54df-9991-f31162102d92'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'La « fenêtre anabolique » de 30 minutes est une obligation stricte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est moins stricte qu’on le dit : c’est l’apport total de la journée qui compte le plus.', 7),
    ('1af69b5e-d759-5998-9b48-c58ffbd9827d'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Que dit-on de la créatine pour un adolescent ?', 'mcq', '["Elle remplace l’entraînement","Elle est sans danger à tout âge sans réserve","Elle n’est pas conseillée avant 18 ans sans avis médical","Elle est obligatoire"]'::jsonb, 2, 'Efficace et étudiée chez l’adulte, elle n’est pas conseillée avant 18 ans sans avis médical.', 8),
    ('99b194f1-77d3-5823-ac7d-d032738cb5aa'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Que recommande l’ANSES à propos des boissons énergisantes pour les adolescents ?', 'mcq', '["En boire avant chaque match","En faire une boisson quotidienne","Les mélanger avec de l’alcool","Les déconseiller"]'::jsonb, 3, 'Ces boissons sont déconseillées aux adolescents, et la caféine n’est pas pour les mineurs.', 9),
    ('8a58abb0-3f7c-53e8-9ad2-d9e6f7fb0f40'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Faire un régime strict ou un jeûne est une bonne idée pendant la croissance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pendant la croissance, le corps a besoin d’énergie et de nutriments : on évite régimes et jeûne.', 10),
    ('4c0e6a63-f8b2-5490-8e9f-42a2e0a5cf4b'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'Pourquoi un complément alimentaire peut-il poser problème à un athlète ?', 'mcq', '["Il peut contenir des substances dopantes non indiquées","Il est toujours gratuit","Il rend invisible aux contrôles","Il est interdit de le manger"]'::jsonb, 0, 'Certains compléments contiennent des produits interdits : le contrôle positif « involontaire » reste un contrôle positif.', 11),
    ('10c3af6d-6850-5fdc-88eb-5777f9fb8b1d'::uuid, 'ff1b46b5-33aa-53bd-989e-0b123c976809'::uuid, 'La veille d’un match, que choisir ?', 'mcq', '["Seulement une boisson énergisante","Pâtes, protéines, légumes et eau, sans nouveauté","Un aliment inconnu pour tester","Rien du tout"]'::jsonb, 1, 'Féculents et protéines habituels, sans essai de nouveauté : on ne teste jamais un aliment le jour J.', 12),
    ('a5326fb8-0b3c-5f20-a57b-7faa7f719dcf'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Quel tissu est touché lors d’une entorse ?', 'mcq', '["Un nerf","Un muscle uniquement","Un ligament","Un os"]'::jsonb, 2, 'Un ligament tient l’articulation ; l’entorse le met à rude épreuve, voire le rompt.', 1),
    ('511338e6-5005-58de-9c76-c856a01a9aaa'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Combien de grades distingue-t-on pour une entorse ?', 'mcq', '["Trois","Sept","Un seul","Deux"]'::jsonb, 0, 'Du simple étirement à la rupture complète, on décrit trois grades.', 2),
    ('3f492d17-30ab-5e11-a17f-ad62d19d7801'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Quelle articulation est la plus souvent touchée par les entorses ?', 'mcq', '["La cheville","Le coude","Le poignet","La nuque"]'::jsonb, 0, 'La cheville encaisse des appuis violents et des torsions : c’est l’entorse la plus fréquente.', 3),
    ('2516e7dc-bc1f-5b34-b82f-3fedbd7a9532'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Que mettent en avant les recommandations « PEACE & LOVE » après la phase initiale ?', 'mcq', '["Masser très fort","Remettre l’articulation en mouvement progressivement","Rester immobile pendant des mois","Forcer le plus vite possible"]'::jsonb, 1, 'Bouger peu à peu, sans douleur vive, aide l’articulation à guérir mieux que l’immobilité totale.', 4),
    ('7e5b5d24-7e28-5d05-ba92-cc300123be82'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Une « tendinite » est en réalité le plus souvent…', 'mcq', '["Un os cassé","Un manque d’eau","Une tendinopathie de surcharge","Un microbe"]'::jsonb, 2, 'Le tendon a reçu trop d’effort trop vite : on adapte la charge et on renforce progressivement.', 5),
    ('9e2c10f1-f761-5f2b-8b11-62ffaa2573d2'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Quelle lésion musculaire est la plus grave ?', 'mcq', '["La contracture","La courbature","Le point de côté","La déchirure"]'::jsonb, 3, 'La déchirure est la rupture la plus étendue ; elle demande 6 semaines et plus.', 6),
    ('cb81542c-7d4c-5be2-ab91-71b0e3728928'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Après un choc à la tête avec confusion, le joueur doit finir le match s’il se sent mieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Au moindre doute, on sort : un second choc sur un cerveau fragilisé peut être grave.', 7),
    ('4c3a7e4b-406c-515b-bfe3-8025de659548'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Parmi ces signes, lequel évoque une commotion ?', 'mcq', '["Mal de tête, confusion, nausée","Une crampe au mollet","Un hoquet","Une courbature"]'::jsonb, 0, 'Maux de tête, confusion, nausées et troubles de la vue sont les signes d’une commotion.', 8),
    ('b8faa790-d05e-543e-bf3d-bb246ddcfd21'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Comment se fait le retour au sport après une commotion ?', 'mcq', '["Sans avis médical","Repos, puis reprise progressive par paliers","Directement en match","Par un sprint maximal"]'::jsonb, 1, 'Le cerveau a besoin de repos, puis d’une reprise graduée sur plusieurs semaines chez un mineur.', 9),
    ('24b51b65-a251-5183-81b2-fdb80eda16f2'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Une contracture dure en général environ…', 'mcq', '["Un jour exactement","Dix ans","Une semaine","Un an"]'::jsonb, 2, 'C’est la lésion musculaire la plus bénigne, d’environ une semaine à titre indicatif.', 10),
    ('19fa60ee-bd0d-59d3-9918-f0d3d5c1111b'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Une douleur qui persiste ou une articulation qui se bloque justifie de consulter un médecin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des signes d’alerte : on consulte au lieu de s’improviser soignant.', 11),
    ('68d1976c-6f1b-5668-8eed-bfc876474b64'::uuid, '7cc6a42a-4722-5b94-9462-a1d07eec2927'::uuid, 'Quelle est la meilleure prévention des blessures ?', 'mcq', '["Ne jamais s’entraîner","Forcer chaque séance","Supprimer l’échauffement","Échauffement, progressivité, renforcement et sommeil"]'::jsonb, 3, 'Un corps préparé, progressivement entraîné et reposé encaisse beaucoup mieux les efforts.', 12),
    ('67dc2c84-2207-5811-8f60-0fa18aa86dfc'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Dans quel pays est né le sport moderne au XIXe siècle ?', 'mcq', '["L’Angleterre","La France","L’Italie","Les États-Unis"]'::jsonb, 0, 'Dans les public schools et les clubs anglais, on a codifié les jeux : des règles écrites, les mêmes pour tous.', 1),
    ('04d2e0a8-be50-5d6a-8659-caad6eeb9bc0'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'En quelle année la Football Association a-t-elle été créée ?', 'mcq', '["1998","1863","1763","1913"]'::jsonb, 1, 'En 1863, elle fixe les premières règles communes du football ; la Rugby Football Union suivra en 1871.', 2),
    ('f3a24e7e-1ea4-5746-b267-ecc973d22d4a'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Quel tournoi de tennis débute en 1877 ?', 'mcq', '["Les Jeux olympiques","Le Tour de France","Wimbledon","Roland-Garros"]'::jsonb, 2, 'Le lawn-tennis est breveté en 1874, et Wimbledon organise son premier tournoi en 1877.', 3),
    ('0b42aebc-fc0d-5a5a-b981-5c96c6c3ca8b'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Un sportif « amateur » est un sportif…', 'mcq', '["payé pour jouer","qui ne s’entraîne jamais","étranger","qui joue par plaisir, sans être payé"]'::jsonb, 3, 'Au XIXe siècle, les amateurs s’opposent aux professionnels, payés pour jouer.', 4),
    ('36f6764d-09ac-59e7-9baa-b9fb3926179e'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Quel club est fondé au Havre en 1872 ?', 'mcq', '["Le Havre Athletic Club","Le Stade français","Le Racing Club de France","Le Paris Saint-Germain"]'::jsonb, 0, 'Le Havre AC, créé en 1872, est l’un des premiers clubs à introduire le sport anglais en France.', 5),
    ('ae80f546-2fa8-5179-ba76-b43862424a07'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Qui a apporté les premiers sports modernes en France ?', 'mcq', '["Aucun étranger","Des Anglais installés en France","Des Espagnols","Des Japonais"]'::jsonb, 1, 'Ce sont des Anglais installés en France qui ont apporté leurs jeux et fondé les premiers clubs.', 6),
    ('d68c2007-2082-5596-af82-9f23529717e2'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Avant le sport, quelle pratique domine à l’école en France ?', 'mcq', '["Le tennis","L’escalade","La gymnastique, inspirée du Turnen allemand","Le rugby"]'::jsonb, 2, 'La gymnastique et les bataillons scolaires devaient former des corps forts avant l’arrivée du sport.', 7),
    ('c4202272-3143-54e1-a4b7-91f64dd41b3a'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Quelle loi permet de créer librement des associations sportives ?', 'mcq', '["La loi de 1789","La loi de 1936","La loi de 2024","La loi de 1901"]'::jsonb, 3, 'La loi de 1901 donne à tous le droit de fonder une association : les clubs se multiplient.', 8),
    ('a81adcdd-4ee8-5e43-9db7-d80a49341e17'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Léo Lagrange est associé…', 'mcq', '["au sport pour tous sous le Front populaire en 1936","à la création du football en 1863","au tennis de 1877","au dopage"]'::jsonb, 0, 'Avec les congés payés, il incarne en 1936 l’idée que le sport et les loisirs sont pour tous.', 9),
    ('502f2d02-81b8-5e20-81bb-260713daaee4'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Le sport moderne est né sans aucune règle écrite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : le sport moderne naît de la codification, c’est-à-dire des règles écrites communes à tous.', 10),
    ('66533a3a-33c7-5a52-a5ca-b96192a00183'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'Le Racing Club de France est créé en 1882.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des premiers clubs français, avec le Havre AC (1872) et le Stade français (1883).', 11),
    ('10ac5edd-4ad0-5465-a923-3d202533e7be'::uuid, '9f075dc7-e84a-5384-a9a1-7026c8fe872d'::uuid, 'En France, l’UNSS organise…', 'mcq', '["les transferts de joueurs","le sport scolaire","le Tour de France","les Jeux olympiques"]'::jsonb, 1, 'L’UNSS propose des compétitions entre établissements : c’est le sport scolaire.', 12),
    ('2f526066-f290-5a42-a428-6428e24b50fc'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Combien de médailles d’or Jesse Owens a-t-il gagnées à Berlin en 1936 ?', 'mcq', '["Dix","Aucune","Quatre","Une"]'::jsonb, 2, 'Ses quatre ors dans l’Allemagne nazie ont contredit le discours de propagande sur la supériorité raciale.', 1),
    ('2683c683-3050-513d-8ec7-86f1e94fb448'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Qui filme les Jeux de Berlin pour le régime nazi ?', 'mcq', '["Alice Milliat","Léo Lagrange","Pierre de Coubertin","Leni Riefenstahl"]'::jsonb, 3, 'La cinéaste Leni Riefenstahl a mis en images les Jeux de 1936.', 2),
    ('0bc0e2b4-9fd6-5954-90ba-033ecf9900dd'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Quel geste Tommie Smith et John Carlos font-ils à Mexico en 1968 ?', 'mcq', '["Ils lèvent le poing ganté de noir","Ils s’agenouillent","Ils quittent le stade","Ils chantent"]'::jsonb, 0, 'Le 16 octobre 1968, poing levé, ils dénoncent le sort des Noirs américains.', 3),
    ('c03ab557-8449-5514-a41a-6146959bb646'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Qui est Peter Norman ?', 'mcq', '["Un dirigeant du CIO","L’Australien deuxième du 200 m, solidaire du geste","Un arbitre","Un entraîneur américain"]'::jsonb, 1, 'Il se montre solidaire des deux Américains sur le podium.', 4),
    ('b8ba0bce-636b-51fa-a19d-b6e59d1ceab1'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Quelle équipe est attaquée aux Jeux de Munich en 1972 ?', 'mcq', '["L’équipe de Chine","L’équipe d’Italie","L’équipe d’Israël","L’équipe de France"]'::jsonb, 2, 'Onze membres de la délégation israélienne sont tués lors de cet attentat.', 5),
    ('0f8b86ad-b968-53d7-9e38-33dfe991d4a5'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Pourquoi les Jeux de Moscou en 1980 sont-ils boycottés par une soixantaine de pays ?', 'mcq', '["À cause d’une grève","À cause de la météo","À cause d’un virus","À cause de l’invasion de l’Afghanistan par l’URSS"]'::jsonb, 3, 'C’est une réaction politique à l’invasion soviétique de l’Afghanistan.', 6),
    ('651705cc-f33e-5b9a-a68d-f01676ba4247'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Qui boycotte les Jeux de Los Angeles en 1984 ?', 'mcq', '["L’URSS et ses alliés","Les États-Unis","La France","Le Japon"]'::jsonb, 0, 'Les Soviétiques répondent au boycott de 1980 : c’est la logique de la guerre froide.', 7),
    ('9a8790da-31b5-52a9-a84d-d23479bde478'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'L’Afrique du Sud, pays de l’apartheid, a été exclue des Jeux de…', 'mcq', '["1936 à 1948","1964 à 1992","1900 à 1924","2000 à 2010"]'::jsonb, 1, 'Le sport a servi de moyen de pression contre l’apartheid.', 8),
    ('0669c339-83f5-5134-b753-14237441e8a4'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Qu’appelle-t-on la « diplomatie du ping-pong » ?', 'mcq', '["Un boycott","Un attentat","Le rapprochement États-Unis–Chine en 1971","Un traité sur le tennis"]'::jsonb, 2, 'Des joueurs de tennis de table ont servi de messagers entre les deux pays en 1971.', 9),
    ('556e6e62-88cf-5b67-97cc-cbb3874019a8'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Le sport est toujours neutre et sans lien avec la politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’histoire montre l’inverse : propagande, boycotts, gestes de protestation… le sport n’est jamais neutre.', 10),
    ('d0cfd43a-01b5-52ed-ad48-5f8b87d5b667'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'Depuis 2022, quel pays est suspendu des compétitions internationales avec des athlètes « neutres » à Paris 2024 ?', 'mcq', '["La Belgique","Le Canada","L’Espagne","La Russie"]'::jsonb, 3, 'Les athlètes russes ne concourent pas sous leur drapeau : ils sont « neutres » à Paris 2024.', 11),
    ('39752e87-54ac-5575-9328-25e2ac202cd9'::uuid, '7fc0ea8d-4def-5a6e-93d9-9ae38e1799fe'::uuid, 'La Coupe du monde 2022 au Qatar a relancé le débat sur…', 'mcq', '["les droits humains","le prix des billets d’avion","la météo","le nombre de buts"]'::jsonb, 0, 'Les conditions de travail et les libertés au Qatar ont nourri la critique de l’événement.', 12),
    ('bf217940-c67f-5bbf-9edf-39349c03c51e'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Combien de femmes participent aux Jeux de Paris en 1900 ?', 'mcq', '["Aucune","22","2 000","220"]'::jsonb, 1, 'Elles sont vingt-deux : les femmes entrent aux Jeux, mais en très petit nombre.', 1),
    ('e56e4ecc-f313-5b24-8821-4c850f5bce73'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Quelle sportive gagne le tournoi de tennis des Jeux de 1900 ?', 'mcq', '["Joan Benoit","Billie Jean King","Charlotte Cooper","Alice Milliat"]'::jsonb, 2, 'Charlotte Cooper, en tennis, est l’une des premières championnes olympiques.', 2),
    ('a98231f7-5675-536b-ae9d-80d76ae57f71'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Qui fonde la FSFI en 1921 ?', 'mcq', '["Pierre de Coubertin","Léo Lagrange","Joan Benoit","Alice Milliat"]'::jsonb, 3, 'Alice Milliat crée la Fédération sportive féminine internationale face au refus de Coubertin.', 3),
    ('ff449399-40aa-5641-ab8e-5b4ecfd588dc'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Où ont lieu les premiers Jeux mondiaux féminins en 1922 ?', 'mcq', '["À Paris","À Londres","À Berlin","À New York"]'::jsonb, 0, 'Paris accueille ces Jeux organisés par Alice Milliat et la FSFI.', 4),
    ('536dff5e-0979-590d-9390-0be3000803d4'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Quel est le point de vue de Coubertin sur les femmes aux Jeux ?', 'mcq', '["Il les choisit lui-même","Il y est hostile","Il les encourage fortement","Il en est indifférent"]'::jsonb, 1, 'Coubertin refuse leur présence, ce qui pousse Alice Milliat à créer ses propres Jeux.', 5),
    ('e66d8ca9-6695-5dd8-8fdf-224525471f71'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Après son entrée aux Jeux en 1928, quelle épreuve féminine est retirée jusqu’en 1960 ?', 'mcq', '["Le relais","Le tennis","Le 800 m","Le saut en longueur"]'::jsonb, 2, 'On a jugé le 800 m « trop dur » pour les femmes, un préjugé sans fondement.', 6),
    ('ddefc81f-f1f4-5588-a9d5-39857df35ab2'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Que fait Kathrine Switzer en 1967 ?', 'mcq', '["Elle gagne Wimbledon","Elle remporte l’or à Paris","Elle fonde la FSFI","Elle court le marathon de Boston avec un dossard"]'::jsonb, 3, 'Elle court le marathon de Boston avec un dossard, à une époque où cela ne se faisait pas.', 7),
    ('4dfb2eea-b52f-515f-93c9-31439f1174d9'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Qui bat Bobby Riggs en 1973 lors de la « bataille des sexes » ?', 'mcq', '["Billie Jean King","Joan Benoit","Clarisse Agbegnenou","Wendie Renard"]'::jsonb, 0, 'La victoire de Billie Jean King devient un symbole mondial de l’égalité.', 8),
    ('ca1856bf-0c1f-5989-bd35-9a5ebfc0b74e'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Qui gagne le premier marathon olympique féminin en 1984 ?', 'mcq', '["Amandine Henry","Joan Benoit","Kathrine Switzer","Alice Milliat"]'::jsonb, 1, 'Joan Benoit remporte le premier marathon olympique féminin, dix-sept ans après Boston 1967.', 9),
    ('414a2242-5911-5eb1-b9b5-c33792889533'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Les Jeux de Paris 2024 sont les premiers à atteindre la parité hommes-femmes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il y a autant d’athlètes femmes que d’hommes : une première dans l’histoire des Jeux.', 10),
    ('3ed1fd5d-1b17-5ddd-8f78-50436d58df8d'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'La parité aux Jeux signifie que tout est égal dans le sport.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La médiatisation, les primes et la présence de dirigeantes restent inégales.', 11),
    ('2c34818d-0afd-57ed-844c-36c47c7ca7f5'::uuid, 'cd521c85-5204-59db-9169-32ce9c94b3a9'::uuid, 'Comment s’appelle le championnat féminin de football devenu professionnel en France en 2024 ?', 'mcq', '["La Coupe du monde","Le Top 14","La Première Ligue","La Ligue des champions"]'::jsonb, 2, 'La Première Ligue marque la professionnalisation du football féminin français.', 12),
    ('c9727ceb-0f59-5077-980d-f2a51cbd46fa'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Quelle est la principale source d’argent d’un championnat de football ?', 'mcq', '["La vente de ballons","Les cours de sport","Les amendes","Les droits de télévision"]'::jsonb, 3, 'Les chaînes paient très cher pour diffuser les matchs : c’est une ressource majeure.', 1),
    ('2ceac69d-993b-58b7-86ce-3f9c25d60642'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Quelle chaîne a fait faillite en 2020 en laissant la Ligue 1 sans diffuseur ?', 'mcq', '["Mediapro","DAZN","Ligue 1+","Canal+"]'::jsonb, 0, 'La faillite de Mediapro en 2020 a fragilisé les finances de la Ligue 1.', 2),
    ('a6c6137d-5f78-5189-9a11-13f2a9b7d8ed'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Quelle chaîne la Ligue a-t-elle lancée elle-même en 2025 ?', 'mcq', '["Eurosport","Ligue 1+","DAZN","Mediapro"]'::jsonb, 1, 'Après DAZN en 2024-25, la Ligue crée sa propre chaîne, Ligue 1+.', 3),
    ('c7657b5c-8300-50e9-bade-88046ff6e885'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Quel joueur détient le record de transfert, 222 millions d’euros en 2017 ?', 'mcq', '["Mbappé","Messi","Neymar","Zidane"]'::jsonb, 2, 'Neymar a été acheté par le PSG pour 222 millions d’euros en 2017.', 4),
    ('207348e6-6961-5117-848a-8eea0938b9ff'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Depuis quelle année le PSG appartient-il au Qatar ?', 'mcq', '["1970","1999","2024","2011"]'::jsonb, 3, 'Depuis 2011, des investisseurs qataris détiennent le club.', 5),
    ('0e7328ef-6100-5441-a8f6-7d032aa5e05e'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'À quoi servent les règles de « durabilité financière » de l’UEFA ?', 'mcq', '["Éviter qu’un club dépense durablement plus qu’il ne gagne","Fixer le prix des billets","Choisir les arbitres","Interdire les sponsors"]'::jsonb, 0, 'Elles limitent les déficits et l’avantage des propriétaires trop riches.', 6),
    ('0893bbc5-b94f-5269-a408-28c90994b398'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'La Premier League anglaise tire des droits TV bien plus élevés que la Ligue 1.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Son marché est beaucoup plus riche : ses droits TV rapportent bien davantage.', 7),
    ('26a26054-4d0e-57d0-a6b7-d8c3786948b9'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Qui finance surtout le comité d’organisation de Paris 2024 ?', 'mcq', '["Aucune entreprise","Le privé","Uniquement les impôts locaux","Les spectateurs seuls"]'::jsonb, 1, 'Le budget d’environ 4,4 milliards d’euros du comité vient surtout de ressources privées.', 8),
    ('2f048502-11e5-5662-be96-827047786606'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Le coût public des Jeux de Paris 2024 est connu avec une précision parfaite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des estimations, comme celle de la Cour des comptes en 2025 : elles se discutent.', 9),
    ('ccb53dd2-4e12-5e99-a254-af157d0c3ea4'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Tous les sportifs gagnent des fortunes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les écarts sont immenses : la majorité des sportifs ne vivent pas de leur sport.', 10),
    ('ae34d221-d1ea-5292-8fb4-d0562ea7f03f'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Quelles marques sont des équipementiers célèbres ?', 'mcq', '["Apple et Google","Danone et Nestlé","Nike et Adidas","Michelin et Renault"]'::jsonb, 2, 'Elles fabriquent les maillots et les chaussures et sponsorisent clubs et athlètes.', 11),
    ('2275b56b-3cee-5189-af50-db844393d3c0'::uuid, '6138f4e4-e944-5f55-9c35-ce2b3b71fb67'::uuid, 'Que désigne l’e-sport ?', 'mcq', '["Le sport en extérieur","Le sport électrique","Un régime alimentaire","Les compétitions de jeux vidéo"]'::jsonb, 3, 'C’est une compétition de jeux vidéo, aussi en plein essor économique.', 12),
    ('ef8cc349-7564-5dd2-9ffd-8114fe85af3f'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Que désigne le dopage ?', 'mcq', '["L’usage de substances ou de méthodes interdites pour améliorer ses performances","Un régime alimentaire","Un type d’entraînement","Une blessure"]'::jsonb, 0, 'C’est de la triche et un danger pour la santé : la liste des produits interdits est mise à jour chaque année.', 1),
    ('2ade4036-6e19-5e0a-bd0a-65271a4973cf'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Quel coureur meurt sur le Mont Ventoux en 1967 ?', 'mcq', '["Willy Voet","Tom Simpson","Lance Armstrong","Ben Johnson"]'::jsonb, 1, 'La mort de Tom Simpson a marqué les esprits et relancé le débat sur le dopage.', 2),
    ('90500d67-5907-5ef3-957f-20575aeb18ce'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Quel sprinter est déclassé après les Jeux de Séoul en 1988 ?', 'mcq', '["Usain Bolt","Carl Lewis","Ben Johnson","Jesse Owens"]'::jsonb, 2, 'Ben Johnson perd son titre sur 100 m à cause d’un contrôle positif.', 3),
    ('e54e8dfe-f22f-55ca-82e4-5047e4caeeb7'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Quelle affaire éclate pendant le Tour de France 1998 ?', 'mcq', '["L’affaire Mediapro","L’affaire Milliat","L’affaire Lagrange","L’affaire Festina"]'::jsonb, 3, 'Willy Voet, soigneur de Festina, est arrêté avec des produits dopants dans sa voiture.', 4),
    ('5292e992-2858-563c-bc4e-49027c4f6e17'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Qu’est-il arrivé à Lance Armstrong en 2012 ?', 'mcq', '["Il a été déchu de ses titres","Il a reçu un trophée","Il a pris sa retraite avec les honneurs","Il a battu un record"]'::jsonb, 0, 'Ses victoires lui ont été retirées après les révélations sur le dopage.', 5),
    ('f9a59e6a-2f96-5e87-9b9a-ba30308cb9c9'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Que révèle le rapport McLaren en 2016 ?', 'mcq', '["Une fraude de billetterie","Un dopage d’État en Russie","Un tournoi de tennis","Un record du monde"]'::jsonb, 1, 'Il met en évidence un système de dopage organisé par l’État russe.', 6),
    ('338f2fe4-d8e3-5674-b1d1-ba28a23e1b5f'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'En quelle année est créée l’Agence mondiale antidopage (AMA) ?', 'mcq', '["2020","1945","1999","1899"]'::jsonb, 2, 'L’AMA naît en 1999 ; son siège est à Montréal.', 7),
    ('15b38533-4bbf-59f4-9f7b-bc94e0bf6f38'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Que fait le passeport biologique ?', 'mcq', '["Il donne le droit de voyager","Il vérifie le casier judiciaire","Il remplace le contrôle urinaire","Il suit les valeurs sanguines de l’athlète dans le temps"]'::jsonb, 3, 'En observant l’évolution du sang, il repère des anomalies même sans produit détecté.', 8),
    ('fdce24aa-2c59-5409-8d8a-e832d3eecc74'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Quelle est la sanction habituelle d’un dopage en principe ?', 'mcq', '["4 ans de suspension","1 jour","Un simple avertissement","Aucune sanction"]'::jsonb, 0, 'Quatre ans en principe, ce qui peut mettre fin à une carrière.', 9),
    ('888f95db-5e83-5c06-b78c-123fe1a1825d'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Que permet une AUT ?', 'mcq', '["Gagner une médaille","Prendre légalement un médicament interdit pour une raison médicale","Se doper sans contrôle","Ne jamais être testé"]'::jsonb, 1, 'L’autorisation à usage thérapeutique est la seule dérogation légale, après examen médical.', 10),
    ('4d8c3150-63cc-5756-83c8-27e3a1fe2846'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'L’EPO épaissit le sang et fait courir un risque cardiaque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un sang plus épais gêne la circulation et peut provoquer des accidents cardiaques.', 11),
    ('773159eb-f6a2-58f4-8fb2-744393cf6f6d'::uuid, '8f888393-2fd0-5d6f-8d40-5ac26523802d'::uuid, 'Si un complément alimentaire contenait un produit interdit à l’insu du sportif, celui-ci n’est pas responsable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’athlète est toujours responsable de ce qu’il avale : « je ne savais pas » ne protège pas.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('sport');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('sport')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 567 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 567 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
